using Xunit;
using EnterpriseDocumentIntelligence.BuildingBlocks.Messaging;using Xunit;
public sealed class MessagingContractTests{[Fact]public void Topics_are_stable(){Assert.Equal("document-events",Topics.DocumentEvents);Assert.Equal("ingestion-events",Topics.IngestionEvents);Assert.Equal("processing-events",Topics.ProcessingEvents);Assert.Equal("embedding-events",Topics.EmbeddingEvents);}[Fact]public void Upload_event_preserves_correlation(){var id=Guid.NewGuid();var e=new DocumentUploaded(Guid.NewGuid(),Guid.NewGuid(),id,Guid.NewGuid(),"blob","application/pdf",1,DateTimeOffset.UtcNow,"corr-1");Assert.Equal(id,e.DocumentId);Assert.Equal("corr-1",e.CorrelationId);}}